package com.pranit.helpdesk.config;
import com.pranit.helpdesk.entity.User; import com.pranit.helpdesk.model.Role; import com.pranit.helpdesk.repository.UserRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataInitializer{@Bean CommandLineRunner seed(UserRepository r,PasswordEncoder e){return a->{create(r,e,"admin","admin@helpdesk.local","Admin@12345",Role.ADMIN);create(r,e,"agent","agent@helpdesk.local","Agent@12345",Role.AGENT);};}private void create(UserRepository r,PasswordEncoder e,String n,String m,String p,Role role){if(r.findByUsername(n).isEmpty()){User u=new User();u.setUsername(n);u.setEmail(m);u.setPassword(e.encode(p));u.setRole(role);r.save(u);}}}
